<script setup lang="ts">
import {ref,computed,watch,onMounted,onUnmounted} from 'vue';import MobileCatalog from './MobileCatalog.vue';import MobileShortDrama from './MobileShortDrama.vue';import MobileEpisodeList from './MobileEpisodeList.vue';import type {Theme,Vod,Category,Section,AppPage,NavItem,Ad,Platform} from '@/domain/types';import FilmModule from './FilmModule.vue';import MobileTabBar from './MobileTabBar.vue';import AppEmptyState from './AppEmptyState.vue';import ThemeCarousel from './ThemeCarousel.vue';import MemberPanel from './MemberPanel.vue';import AdSpot from './AdSpot.vue';import PufferMark from './PufferMark.vue';import StartupScreen from './StartupScreen.vue';import AppIcon from './AppIcon.vue';import AnnouncementBanner from './AnnouncementBanner.vue';import ClientPrompts from './ClientPrompts.vue';import type {UpdateTarget} from '@/domain/client-notifications';import {api,assetUrl,memberApi} from '@/services/api';import {getLibrary,getHistory,toggleFavorite,remember} from '@/services/library';import {available,adsAt,pageNames} from '@/domain/presentation';
const props=withDefaults(defineProps<{theme:Theme;items:Vod[];categories:Category[];sectionItems?:Record<string,Vod[]>;demo?:boolean;editing?:boolean;selected?:string;page?:AppPage;platform?:Platform;error?:string;startupPreview?:number;announcementPreview?:number;updatePreview?:number;studio?:boolean;templateKey?:string}>(),{page:'home',platform:'mobile',sectionItems:()=>({})});const emit=defineEmits<{select:[id:string];page:[page:AppPage];retry:[]}>();
const page=ref<AppPage>(props.page),film=ref<Vod|null>(null),query=ref(''),searchAttempted=ref(false),categoryId=ref(''),localItems=ref<Vod[]|null>(props.page==='shortdrama'?[]:null),loading=ref(false),message=ref(''),source=ref(0),episode=ref(0),playUrl=ref(''),favorite=ref(false),collection=ref<Vod[]>([]),fullScreen=ref(false),catalogPage=ref(1),catalogPages=ref(1),shortIndex=ref(0),shortFavorite=ref(false),startup=ref<Ad|null>(null),adElapsed=ref(0);const bootVisible=ref(false),updateMessage=ref(''),appVersion=ref(String(import.meta.env.VITE_HETUN_APP_VERSION||'0.0.1'));let bootTimer:ReturnType<typeof setTimeout>|undefined;
const activeShortEntryId=ref('');const shortEntry=computed(()=>{const entries=[...props.theme.navigation,...props.theme.categories].filter(n=>n.enabled&&n.page==='shortdrama');return entries.find(n=>n.id===activeShortEntryId.value)||entries[0];});
const menuOpen=ref(false),introOpen=ref(false);const serviceMenuEnabled=computed(()=>props.theme.features.serviceMenu!==false);const mobileClient=computed(()=>props.platform==='mobile');const nativePhone=computed(()=>mobileClient.value&&props.theme.pageStyles.design==='youku');const rootPages=['home','mine','member','shortdrama'];const showBottom=computed(()=>!nativePhone.value||(!film.value&&(rootPages.includes(page.value)||nav.value.some(n=>n.page===page.value)&&!['search','category','settings','disclaimer','privacy','about','history','library'].includes(page.value))));const catalogScreen=computed(()=>nativePhone.value&&['category','ranking','search'].includes(page.value));const accountView=ref<''|'account'|'membership'>(''),memberProfile=ref<any>(null),accountRevision=ref(0),promptRef=ref<any>(null),updateBlocked=ref(false),bootComplete=ref(false),versionReady=ref(true);const updateTarget=ref<UpdateTarget>('web');
// #ifdef APP-PLUS
versionReady.value=false;updateTarget.value=uni.getSystemInfoSync().platform==='ios'?'ios':'android';
// #endif
if(props.studio)updateTarget.value='android';
const seenAds=new Set<string>();let timer:ReturnType<typeof setInterval>|undefined,requestGeneration=0;
const nav=computed(()=>props.theme.navigation.filter(n=>n.enabled&&available(props.theme,n.page)));const tabs=computed(()=>props.theme.categories.filter(n=>n.enabled&&available(props.theme,n.page)));const visible=computed(()=>page.value==='library'||page.value==='history'?collection.value:localItems.value??props.items);const sections=computed(()=>props.theme.sections.filter(s=>s.enabled&&(s.page||'home')===page.value));const lightMode=computed(()=>{let hex=props.theme.colors.background.replace('#','');if(hex.length===3)hex=hex.split('').map(c=>c+c).join('');return hex.length===6&&(parseInt(hex.slice(0,2),16)*.299+parseInt(hex.slice(2,4),16)*.587+parseInt(hex.slice(4,6),16)*.114)>160;});
const vars=computed(()=>({'--bg':props.theme.colors.background,'--surface':props.theme.colors.surface,'--text':props.theme.colors.text,'--muted':props.theme.colors.muted,'--accent':props.theme.colors.accent,'--mobile-card':lightMode.value?'#ffffff':props.theme.colors.surface,'--mobile-nav':lightMode.value?'#ffffff':props.theme.colors.background,'--mobile-line':lightMode.value?'#1522350d':'#ffffff0f','--mobile-soft':lightMode.value?'#f4f6f9':'#ffffff06','--mobile-shadow':lightMode.value?'0 4px 24px #18243a04':'0 4px 24px #0000000c'}));
const serviceLinks=computed(()=>[{page:'member' as AppPage,label:'会员权益',icon:'member',enabled:props.theme.features.memberCard},{page:'library' as AppPage,label:'我的收藏',icon:'favorite',enabled:true},{page:'schedule' as AppPage,label:'影片排期',icon:'schedule',enabled:props.theme.features.schedule},{page:'settings' as AppPage,label:'应用设置',icon:'settings',enabled:true},{page:'disclaimer' as AppPage,label:'免责声明',icon:'shield',enabled:true},{page:'privacy' as AppPage,label:'隐私政策',icon:'shield',enabled:true},{page:'about' as AppPage,label:'关于我们',icon:'info',enabled:true}].filter(s=>s.enabled));const currentEpisodes=computed(()=>film.value?.sources[source.value]?.episodes||[]);const generic=computed<Section>(()=>({id:'page-list',title:page.value==='search'?'搜索结果':pageNames[page.value],subtitle:'',kind:'poster',style:page.value==='ranking'?'ranking':'grid3',orderBy:page.value==='ranking'?'score':'latest',source:'latest',categoryId:'',limit:60,columns:3,enabled:true,showMore:false}));
watch(()=>props.page,p=>{if(p!==page.value)go(p);});watch(()=>props.editing,v=>{if(!v)startupAd();});watch(()=>props.theme.features,()=>{if(!serviceMenuEnabled.value)menuOpen.value=false;if(!available(props.theme,page.value))go('home');if(!props.theme.features.memberCard&&accountView.value==='membership')accountView.value='';},{deep:true,immediate:true});
watch(()=>shortEntry.value?.categoryId||'',id=>{if(page.value==='shortdrama'&&id!==categoryId.value)go('shortdrama',id,activeShortEntryId.value);});
function go(target:AppPage,id='',entryId=''){if(updateBlocked.value||!available(props.theme,target))return;accountView.value='';menuOpen.value=false;introOpen.value=false;requestGeneration++;loading.value=false;film.value=null;playUrl.value='';message.value='';page.value=target;activeShortEntryId.value=target==='shortdrama'?entryId:'';categoryId.value=id||(target==='shortdrama'?shortEntry.value?.categoryId||'':'');localItems.value=target==='shortdrama'?[]:null;query.value='';searchAttempted.value=false;catalogPage.value=1;catalogPages.value=1;shortIndex.value=0;if(target==='library')collection.value=getLibrary();if(target==='history')collection.value=getHistory();if(target==='category'||target==='ranking'||(target==='shortdrama'&&categoryId.value))fetchCatalog();emit('page',target);}
async function openId(id:string){const v=props.items.find(v=>v.id===id);if(v){await open(v);return;}if(props.demo){message.value='示例片库没有此影片。';return;}const generation=++requestGeneration;loading.value=true;try{const c=await api.catalog(1,'','',id);if(generation!==requestGeneration)return;if(c.items[0])await open(c.items[0]);else message.value='影片不存在或已下架。';}catch(e){if(generation===requestGeneration)message.value=(e as Error).message;}finally{if(generation===requestGeneration)loading.value=false;}}
let shortTouchY=0;function shortTouchStart(e:any){shortTouchY=e.changedTouches?.[0]?.clientY||0;}function shortTouchEnd(e:any){const delta=(e.changedTouches?.[0]?.clientY||0)-shortTouchY;if(Math.abs(delta)>45)stepShort(delta>0?-1:1);}function stepShort(by:number){shortIndex.value=Math.max(0,Math.min(visible.value.length-1,shortIndex.value+by));}function favoriteShort(){const v=visible.value[shortIndex.value];if(v)shortFavorite.value=toggleFavorite(v);}watch(()=>visible.value[shortIndex.value]?.id,()=>{shortFavorite.value=getLibrary().some(v=>v.id===visible.value[shortIndex.value]?.id);},{immediate:true});
function navigate(n:NavItem){go(n.page,n.categoryId,n.id);}
function clearSearch(){query.value='';searchAttempted.value=false;localItems.value=[];message.value='';loading.value=false;requestGeneration++;catalogPage.value=1;catalogPages.value=1;}
async function fetchCatalog(more=false){if(page.value==='search'){query.value=query.value.trim();if(!query.value){clearSearch();return;}searchAttempted.value=true;if(!more)localItems.value=[];}const generation=++requestGeneration;loading.value=true;message.value='';try{if(props.demo){localItems.value=props.items.filter(v=>(!query.value||v.title.includes(query.value))&&(!categoryId.value||v.categoryId===categoryId.value));return;}const result=await api.catalog(more?catalogPage.value+1:1,query.value,categoryId.value);if(generation!==requestGeneration)return;localItems.value=more?[...(localItems.value||[]),...result.items]:result.items;catalogPage.value=result.page;catalogPages.value=result.pages;}catch(e){if(generation===requestGeneration)message.value=(e as Error).message;}finally{if(generation===requestGeneration)loading.value=false;}}
function searchFor(value:string){query.value=value;fetchCatalog();}function bindCategory(id:string){categoryId.value=id;if(page.value!=='search'||searchAttempted.value)fetchCatalog();}async function playResult(v:Vod){await open(v);if(film.value?.id===v.id)await watchFilm();}async function playEpisodeResult(v:Vod,index:number){await open(v);if(film.value?.id!==v.id)return;episode.value=index;await watchFilm();}function switchDetailSource(index:number){requestGeneration++;loading.value=false;source.value=index;episode.value=0;playUrl.value='';message.value='';}function playDetailEpisode(index:number){episode.value=index;watchFilm();}function nextDetailEpisode(){if(episode.value+1<currentEpisodes.value.length){episode.value++;watchFilm();}}function closeFilm(){film.value=null;playUrl.value='';introOpen.value=false;requestGeneration++;loading.value=false;message.value='';}function childBack(){if(film.value){closeFilm();return;}go(['settings','history','library'].includes(page.value)?'mine':['privacy','disclaimer','about'].includes(page.value)?'settings':'home');}
function more(s:Section){go('category',s.categoryId||'');}
async function open(v:Vod){if(updateBlocked.value)return;if(props.editing){emit('select','hero');return;}const generation=++requestGeneration;introOpen.value=false;film.value=v;favorite.value=getLibrary().some(i=>i.id===v.id);source.value=0;episode.value=0;playUrl.value='';message.value='';if(!props.demo){loading.value=true;try{const result=await api.catalog(1,'','',v.id);if(generation===requestGeneration&&film.value?.id===v.id&&result.items[0])film.value=result.items[0];}catch(e){if(generation===requestGeneration)message.value=(e as Error).message;}finally{if(generation===requestGeneration)loading.value=false;}}}
function toggle(){if(film.value)favorite.value=toggleFavorite(film.value);}
async function watchFilm(){if(updateBlocked.value)return;if(!film.value)return;message.value='';playUrl.value='';if(props.demo){message.value='这是原创设计示例。连接 CMS 并安装权限适配后播放真实影片。';return;}if(!currentEpisodes.value[episode.value]){message.value='当前线路没有可播放集数。';return;}const generation=++requestGeneration,playingId=film.value.id,playingSource=source.value,playingEpisode=episode.value;loading.value=true;try{const result=await api.playback(playingId,playingSource+1,playingEpisode+1);if(generation!==requestGeneration||film.value?.id!==playingId||source.value!==playingSource||episode.value!==playingEpisode)return;if(!/^https?:\/\//.test(result.url))throw new Error('播放地址不受支持。');playUrl.value=result.url;if(!nativePhone.value)remember(film.value);}catch(e){if(generation===requestGeneration)message.value=(e as Error).message;}finally{if(generation===requestGeneration)loading.value=false;}}
function adOpen(ad:Ad){if(props.editing){emit('select','ads');return;}if(ad.url){
// #ifdef H5
window.open(ad.url,'_blank','noopener,noreferrer');
// #endif
// #ifdef APP-PLUS
plus.runtime.openURL(ad.url);
// #endif
}else go(ad.page);}
function closeAd(){if(startup.value&&adElapsed.value>=startup.value.skipAfter){startup.value=null;if(timer)clearInterval(timer);bootComplete.value=true;}}
function showBoot(){if(bootTimer)clearTimeout(bootTimer);if(!props.theme.startup.enabled){startupAd();return;}bootComplete.value=false;bootVisible.value=true;bootTimer=setTimeout(closeBoot,props.theme.startup.duration*1000);}
function closeBoot(){bootVisible.value=false;if(bootTimer)clearTimeout(bootTimer);startupAd();}
watch(()=>props.startupPreview,showBoot);
function checkUpdate(){promptRef.value?.checkUpdate();}
function noticeOpen(){const n=props.theme.announcement;if(props.editing){emit('select','notice');return;}if(n.url)adOpen({...props.theme.ads[0],url:n.url} as Ad);else if(n.page!=='home')go(n.page);}
function showAccount(membership=false){if(updateBlocked.value)return;if(membership&&!props.theme.features.memberCard)return;accountView.value=membership?'membership':'account';}
function setBlocked(value:boolean){updateBlocked.value=value;if(value)playUrl.value='';}
defineExpose({blocking:updateBlocked});
function receiveProfile(value:any){memberProfile.value=value;accountRevision.value++;}
function shortcuts(){return [{page:'library' as AppPage,label:'我的收藏',icon:'♡'},{page:'history' as AppPage,label:'观看历史',icon:'◷'},props.theme.features.schedule?{page:'schedule' as AppPage,label:'影片排期',icon:'▤'}:{page:'category' as AppPage,label:'影片分类',icon:'◇'},props.theme.features.ranking?{page:'ranking' as AppPage,label:'排行榜',icon:'↗'}:{page:'settings' as AppPage,label:'应用设置',icon:'⚙'}];}
function startupAd(){if(props.editing){bootComplete.value=true;return;}const ad=adsAt(props.theme,'startup').find(a=>a.frequency==='always'||!seenAds.has(a.id));if(!ad){bootComplete.value=true;return;}bootComplete.value=false;startup.value=ad;adElapsed.value=0;seenAds.add(ad.id);timer=setInterval(()=>{adElapsed.value++;if(adElapsed.value>=ad.duration){startup.value=null;if(timer)clearInterval(timer);bootComplete.value=true;}},1000);}
// #ifdef H5
const shell=ref<any>(null);function remote(event:KeyboardEvent){if(updateBlocked.value||props.platform!=='tv'||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key))return;const el=shell.value?.$el||shell.value;const list=Array.from(el?.querySelectorAll('[tabindex="0"],button')||[]) as HTMLElement[];if(!list.length)return;event.preventDefault();const i=list.indexOf(document.activeElement as HTMLElement);list[(i+(event.key==='ArrowLeft'||event.key==='ArrowUp'?-1:1)+list.length)%list.length]?.focus();}
// #endif
onMounted(()=>{if(page.value==='shortdrama')go('shortdrama');if(uni.getStorageSync('hetun-member-token'))memberApi.profile().then(v=>{memberProfile.value=v.profile;}).catch(()=>{memberProfile.value=null;});if(!props.editing)showBoot();else bootComplete.value=true;
// #ifdef APP-PLUS
plus.runtime.getProperty(plus.runtime.appid||'',info=>{appVersion.value=info.version||appVersion.value;versionReady.value=true;});
// #endif
// #ifdef H5
window.addEventListener('keydown',remote);
// #endif
});onUnmounted(()=>{requestGeneration++;if(bootTimer)clearTimeout(bootTimer);if(timer)clearInterval(timer);
// #ifdef H5
window.removeEventListener('keydown',remote);
// #endif
});
</script>
<template><view class="experience" ref="shell" :style="vars" :class="['device-'+platform,'design-'+theme.pageStyles.design,'page-'+page,{'edit-mode':editing,'mode-light':lightMode,'phone-native':nativePhone,'film-active':!!film}]"><view class="experience-body">
<view v-if="mobileClient&&!film&&page==='search'" class="native-searchbar"><view class="native-back" role="button" aria-label="返回首页" @click="childBack"><AppIcon name="back" :size="22" :color="theme.colors.text"/></view><PufferMark :size="20" :color="theme.colors.accent"/><view class="search"><input class="search-input" v-model="query" placeholder="搜索电影、电视剧、综艺" confirm-type="search" aria-label="搜索影片" @confirm="fetchCatalog()"/><view v-if="query" class="search-clear" role="button" aria-label="清空搜索" @click="clearSearch"><AppIcon name="close" :size="14" :color="theme.colors.muted"/></view></view><button class="native-search-submit" :disabled="loading" @click="fetchCatalog()">搜索</button></view>
<view v-else-if="mobileClient&&!film&&!rootPages.includes(page)" class="native-pagebar"><view class="native-back" role="button" aria-label="返回" @click="childBack"><AppIcon name="back" :size="22" :color="theme.colors.text"/></view><view v-if="['category','ranking'].includes(page)" class="native-page-tabs"><text :class="{active:page==='category'}" @click="go('category',categoryId)">筛选</text><text v-if="theme.features.ranking" :class="{active:page==='ranking'}" @click="go('ranking',categoryId)">榜单</text></view><text v-else class="native-page-name">{{pageNames[page]}}</text><view v-if="['category','ranking','history','library'].includes(page)" role="button" aria-label="搜索" @click="go('search')"><AppIcon name="search" :size="21" :color="theme.colors.text"/></view><view v-else class="header-spacer"/></view>
<view v-if="mobileClient&&!film&&page==='mine'" class="account-toolbar" aria-label="个人中心操作栏"><view role="button" aria-label="观看历史" tabindex="0" @click="go('history')" @keydown.enter="go('history')"><AppIcon name="history" :size="22" :color="theme.colors.text"/></view><view role="button" aria-label="应用设置" tabindex="0" @click="go('settings')" @keydown.enter="go('settings')"><AppIcon name="settings" :size="22" :color="theme.colors.text"/></view></view>
<view v-if="!mobileClient||(!film&&page==='home')" class="topbar" :class="{'header-brand':theme.pageStyles.header==='brand','toolbar-only':['mine','member','shortdrama'].includes(page)&&theme.pageStyles.design==='youku'}"><view v-if="platform!=='mobile'||serviceMenuEnabled||(!nativePhone&&page==='search')" class="toolbar-menu" role="button" :aria-expanded="nativePhone?menuOpen:undefined" :aria-label="nativePhone?'打开服务菜单':page==='search'?'返回首页':'打开分类'" tabindex="0" @click="nativePhone?menuOpen=!menuOpen:go(page==='search'?'home':'category')" @keydown.enter="nativePhone?menuOpen=!menuOpen:go(page==='search'?'home':'category')"><AppIcon :name="page==='search'?'back':'menu'" :size="22" :color="theme.colors.text"/></view><view class="brand" v-if="theme.pageStyles.header==='brand'" @click="editing?emit('select','brand'):go('home')"><image v-if="theme.brand.logo" :src="assetUrl(theme.brand.logo)"/><PufferMark v-else :size="25" :color="theme.colors.accent"/><text>{{theme.brand.name}}</text></view><view v-if="!(['mine','member','shortdrama'].includes(page)&&theme.pageStyles.design==='youku')" class="search" @click="page!=='search'&&!editing&&go('search')"><AppIcon name="search" :size="19" :color="theme.colors.muted"/><input v-if="page==='search'" class="search-input" v-model="query" placeholder="搜索电影、电视剧、综艺" confirm-type="search" aria-label="搜索影片" @click.stop @confirm="fetchCatalog()"/><text v-else class="search-placeholder">搜索电影、电视剧、综艺</text><view v-if="page==='search'&&query" class="search-clear" role="button" aria-label="清空搜索" @click.stop="clearSearch" tabindex="0" @keydown.enter="clearSearch"><AppIcon name="close" :size="15" :color="theme.colors.muted"/></view><button v-if="page==='search'" class="search-submit" :disabled="loading" @click.stop="fetchCatalog()">搜索</button><text v-else class="search-filter" @click.stop="go('category')">筛选</text></view><view v-if="theme.pageStyles.design==='youku'&&!(['mine','member','shortdrama'].includes(page))" class="toolbar-brand" @click="go('mine')"><image v-if="theme.brand.logo" :src="assetUrl(theme.brand.logo)"/><PufferMark v-else :size="27" :color="theme.colors.accent"/></view><view v-else class="toolbar-actions"><view v-if="page==='mine'&&theme.pageStyles.design==='youku'" role="button" aria-label="应用设置" tabindex="0" @click="go('settings')" @keydown.enter="go('settings')"><AppIcon name="settings" :size="22" :color="theme.colors.text"/></view><view role="button" aria-label="观看历史" tabindex="0" @click="go('history')" @keydown.enter="go('history')"><AppIcon name="history" :size="22" :color="theme.colors.text"/></view><view v-if="theme.features.schedule" role="button" aria-label="影片排期" tabindex="0" @click="go('schedule')" @keydown.enter="go('schedule')"><AppIcon name="schedule" :size="21" :color="theme.colors.text"/></view></view></view><view v-if="error" class="status"><text>{{error}}</text><text @click="emit('retry')">重试</text></view><view v-if="loading" class="status">正在读取…</view><view v-if="message" class="status">{{message}}</view>
<template v-if="film"><template v-if="nativePhone"><view class="native-player"><video v-if="playUrl" class="player" :src="playUrl" :poster="assetUrl(film.poster)" autoplay controls object-fit="contain" :show-fullscreen-btn="true" :enable-progress-gesture="true" :key="film.id+'-'+source+'-'+episode" :title="film.title" @play="remember(film)" @ended="nextDetailEpisode" @error="message='视频加载失败，请检查线路或切换集数。'"/><view v-else class="player-cover" @click="watchFilm"><image :src="assetUrl(film.poster)" mode="aspectFill"/><view class="player-cover-shade"/><button class="player-start" :disabled="loading" @click.stop="watchFilm"><AppIcon name="play" :size="34" color="#fff"/><text>{{loading?'正在读取':'播放'}}</text></button></view><view v-if="!playUrl" class="player-back" role="button" aria-label="返回影片列表" @click="closeFilm"><AppIcon name="back" :size="23" color="#fff"/></view></view><view class="native-film-body"><view class="detail-channel"><text :class="{active:!introOpen}" @click="introOpen=false">视频</text><text :class="{active:introOpen}" @click="introOpen=true">简介</text><view role="button" aria-label="返回影片列表" @click="closeFilm">返回 ›</view></view><view class="detail-title-row"><text>{{film.title}}</text><text @click="introOpen=!introOpen">简介 ›</text></view><text class="detail-tags">{{[film.score&&film.score+'分',film.year,film.area,film.category,film.note].filter(Boolean).join(' · ')}}</text><view class="detail-actions"><view @click="toggle"><AppIcon name="favorite" :size="23" :color="favorite?theme.colors.accent:theme.colors.text"/><text>{{favorite?'已收藏':'收藏'}}</text></view><view @click="go('history')"><AppIcon name="history" :size="23" :color="theme.colors.text"/><text>观看历史</text></view></view><view v-if="introOpen" class="native-intro"><text>{{film.description||'暂无简介'}}</text><text v-if="film.actors">主演：{{film.actors}}</text><text v-if="film.director">导演：{{film.director}}</text></view><AdSpot v-for="ad in adsAt(theme,playUrl?'player':'detail')" :key="ad.id" :ad="ad" @open="adOpen"/><MobileEpisodeList :film="film" :source="source" :episode="episode" :colors="theme.colors" @source="switchDetailSource" @episode="playDetailEpisode"/></view><FilmModule v-if="items.some(v=>v.id!==film?.id)" :theme="theme" :section="{...generic,title:'相关推荐',limit:6,gap:4,radius:3,ratio:'3/4',showMore:false}" :items="items.filter(v=>v.id!==film?.id)" @open="open"/></template><template v-else><view class="detail-back" @click="film=null;playUrl=''">‹ 返回{{pageNames[page]}}</view><video v-if="playUrl" class="player" :src="playUrl" autoplay controls :title="film.title" @error="message='视频加载失败，请检查线路或切换集数。'"/><view class="film-detail"><image class="detail-poster" :src="assetUrl(film.poster)" mode="aspectFill"/><view><text class="detail-title">{{film.title}}</text><text class="detail-meta">{{film.score}} · {{film.year}} · {{film.category}}</text><text class="detail-meta">{{film.note}}</text><button class="primary" :disabled="loading" @click="watchFilm">▶ 立即观看</button><button class="secondary" @click="toggle">{{favorite?'已收藏 ✓':'＋ 收藏'}}</button></view></view><AdSpot v-for="ad in adsAt(theme,playUrl?'player':'detail')" :key="ad.id" :ad="ad" @open="adOpen"/><view class="detail-copy"><text class="page-title">剧情简介</text><text>{{film.description||'暂无简介'}}</text><text v-if="film.actors">主演：{{film.actors}}</text><text v-if="film.director">导演：{{film.director}}</text></view><view class="chips"><text v-for="(s,i) in film.sources" :key="i" :class="{chosen:source===i}" @click="source=i;episode=0;playUrl=''">{{s.name}}</text></view><view class="chips"><text v-for="(e,i) in currentEpisodes" :key="i" :class="{chosen:episode===i}" @click="episode=i;watchFilm()">{{e.name}}</text></view></template></template>
<template v-else><template v-if="page==='home'"><view class="category-tabs"><text v-for="n in tabs" :key="n.id" :class="{'category-current':n.page==='home'}" tabindex="0" @click="editing?emit('select','categories'):navigate(n)" @keydown.enter="navigate(n)">{{n.label}}</text></view><ThemeCarousel :native-mobile="nativePhone" :theme="theme" :items="items" :editing="editing" @open="open" @id="openId" @page="go($event as AppPage)" @select="emit('select',$event)"/><view class="festival" v-if="theme.festival.enabled&&theme.festival.kind!=='none'">{{theme.festival.kind==='spring'?'✦ 新春好戏 · 一起相聚':theme.festival.kind==='midautumn'?'☾ 月圆人团圆 · 光影相伴':'✧ 冬日光影 · 温暖相伴'}}</view><AnnouncementBanner :notice="theme.announcement" @open="noticeOpen"/><view class="feature-links"><text v-if="theme.features.shortdrama" @click="go('shortdrama')">▷ 短剧</text><text v-if="theme.features.ranking" @click="go('ranking')">↗ 排行榜</text><text v-if="theme.features.schedule" @click="go('schedule')">▤ 排期表</text></view><AdSpot v-for="ad in adsAt(theme,'home')" :key="ad.id" :ad="ad" @open="adOpen"/></template>
